public List<String> letterCombinations(String digits) {
    List<String> results = new ArrayList<>();
    if (digits == null || digits.isEmpty()) return results;   // empty input → []
    String[] map = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    backtrack(digits, 0, map, new StringBuilder(), results);
    return results;
}

private void backtrack(String digits, int index, String[] map,
                       StringBuilder path, List<String> results) {
    if (index == digits.length()) {
        results.add(path.toString());          // all digits used → record built string
        return;
    }
    String letters = map[digits.charAt(index) - '0'];   // this digit's alphabet
    for (int i = 0; i < letters.length(); i++) {
        path.append(letters.charAt(i));                 // choose
        backtrack(digits, index + 1, map, path, results); // explore next digit
        path.deleteCharAt(path.length() - 1);           // un-choose
    }
}

