def letterCombinations(self, digits: str) -> list[str]:
    if not digits:
        return []                              # empty input → []
    mapping = {
        "2": "abc", "3": "def", "4": "ghi", "5": "jkl",
        "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz",
    }
    results: list[str] = []

    def backtrack(index: int, path: list[str]) -> None:
        if index == len(digits):
            results.append("".join(path))      # all digits used → record built string
            return
        for letter in mapping[digits[index]]:  # this digit's alphabet
            path.append(letter)                # choose
            backtrack(index + 1, path)         # explore next digit
            path.pop()                         # un-choose

    backtrack(0, [])
    return results

